nginx_config:
daemon off;
master_process on;
worker_processes 1;
pid /tmp/aegisx-bench-0n5nax9_/nginx.pid;
error_log /tmp/aegisx-bench-0n5nax9_/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-0n5nax9_/body;
    proxy_temp_path /tmp/aegisx-bench-0n5nax9_/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 127.0.0.1:36297; keepalive 256; }
    server {
        listen 127.0.0.1:43887 reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 127.0.0.1:36297;
            proxy_request_buffering off;
            proxy_buffering off;
            proxy_pass http://origin;
        }
    }
}
